"""Copy the proven v3 sender, adding only the human-selected third room."""
from pathlib import Path

HERE=Path(__file__).resolve().parent
old=HERE/'worker_sender_v3';out=HERE/'worker_sender_v4';out.mkdir(exist_ok=True)
def replace(text, before, after):
    if before not in text:raise ValueError('Expected v3 source not found')
    return text.replace(before,after)
c=(old/'native_sender.c').read_text(encoding='utf-8')
c=replace(c,'!strcmp(room,"654321@chatroom");','!strcmp(room,"654321@chatroom") || !strcmp(room,"777777@chatroom");')
c=replace(c,'!strcmp(room,"90000000006@chatroom");','!strcmp(room,"90000000006@chatroom") || !strcmp(room,"90000000001@chatroom");')
c=replace(c,'!strcmp(room,"90000000001@chatroom");','!strcmp(room,"90000000001@chatroom") || !strcmp(room,"90000000005@chatroom");')
c=replace(c,'!strcmp(room,"777777@chatroom");','!strcmp(room,"777777@chatroom") || !strcmp(room,"888888@chatroom");')
(out/'native_sender.c').write_text(c,encoding='utf-8')
(out/'native_sender.h').write_bytes((old/'native_sender.h').read_bytes())
fixture=(old/'send_fixture.c').read_text(encoding='utf-8')
fixture=replace(fixture,'strcmp(value(&request->room),"654321@chatroom"))','strcmp(value(&request->room),"654321@chatroom") && strcmp(value(&request->room),"777777@chatroom"))')
fixture=replace(fixture,'strcmp(value(&request->room),"777777@chatroom"))','strcmp(value(&request->room),"777777@chatroom") && strcmp(value(&request->room),"888888@chatroom"))')
(out/'send_fixture.c').write_text(fixture,encoding='utf-8')
build=(old/'build.py').read_text(encoding='utf-8').replace('worker-sender-v3','worker-sender-v4')
(out/'build.py').write_text(build,encoding='utf-8')
runner=(old/'run.py').read_text(encoding='utf-8').replace('worker-sender-v3','worker-sender-v4').replace('multi-sender-fixture.json','three-group-sender-fixture.json')
runner=replace(runner,"('123456@chatroom','654321@chatroom')","('123456@chatroom','654321@chatroom','777777@chatroom')")
runner=replace(runner,"('90000000003@chatroom','90000000006@chatroom')","('90000000003@chatroom','90000000006@chatroom','90000000001@chatroom')")
runner=replace(runner,"'777777@chatroom')","'777777@chatroom','888888@chatroom')")
runner=replace(runner,"'90000000001@chatroom')","'90000000001@chatroom','90000000005@chatroom')")
runner=replace(runner,"stopped = action(child.pid, 'stop', fixture=True)","three_queue = action(child.pid, 'send', TEST_TEXT, True, room='777777@chatroom')\n        three = wait_for(child.pid, 3)\n        stopped = action(child.pid, 'stop', fixture=True)")
runner=replace(runner,"and two['sender']['disposed'] == 2 and not stopped['return_code']","and two['sender']['disposed'] == 2 and not three_queue['return_code']\n                  and three['sender']['callbacks'] == 3 and three['sender']['disposed'] == 3\n                  and three['execution_thread'] == three['worker_thread']\n                  and three['context_failures'] == 0 and not stopped['return_code']")
runner=replace(runner,'report = dict(two, passed=passed','report = dict(three, passed=passed')
runner=replace(runner,'second_group_verified=passed','second_group_verified=passed, third_group_verified=passed')
runner=replace(runner,"stopped = action(child.pid, 'stop', fixture=True)","four_queue = action(child.pid, 'send', TEST_TEXT, True, room='888888@chatroom')\n        four = wait_for(child.pid, 4)\n        stopped = action(child.pid, 'stop', fixture=True)")
runner=replace(runner,"and three['context_failures'] == 0 and not stopped['return_code']","and three['context_failures'] == 0 and not four_queue['return_code']\n                  and four['sender']['callbacks'] == 4 and four['sender']['disposed'] == 4\n                  and four['context_failures'] == 0 and not stopped['return_code']")
runner=replace(runner,'report = dict(three, passed=passed','report = dict(four, passed=passed')
runner=replace(runner,'third_group_verified=passed','third_group_verified=passed, fourth_group_verified=passed')
(out/'run.py').write_text(runner,encoding='utf-8')
print('Prepared v4: same sender ABI and worker logic, exactly four permitted groups')
